"""Lossless column-order optimizer for character-prefix caching."""

from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Optimize row order and lossless per-row column permutations."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize one scalar exactly as scoring does, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length with binary-searched C-level substring comparisons."""
        low = 0
        high = min(len(left), len(right))
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each source row using its supplied column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    @classmethod
    def _group_score(cls, cells, rows, order) -> int:
        """Score a single row group using the exact sorted-string LCP objective."""
        values = [
            "".join(cells[row, column] for column in order)
            for row in rows
        ]

        if len(values) < 2:
            return 0

        values.sort()
        return sum(
            cls._lcp(values[index - 1], values[index])
            for index in range(1, len(values))
        )

    @staticmethod
    def _repeat_mass(values) -> int:
        """Return length-weighted ordered-pair repetition for one column."""
        counts = {}
        lengths = {}

        for value in values:
            counts[value] = counts.get(value, 0) + 1
            if value not in lengths:
                lengths[value] = len(value)

        return sum(
            lengths[value] * count * (count - 1)
            for value, count in counts.items()
        )

    def _frequency_order(self, cells) -> List[int]:
        """Rank columns by the required length-weighted repeated-value heuristic."""
        _, columns = cells.shape
        ranked = []

        for column in range(columns):
            score = self._repeat_mass(cells[:, column])
            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _cooccurrence_order(self, cells) -> List[int]:
        """Build a bounded graph-seriation order from repeated-value co-occurrence."""
        rows, columns = cells.shape

        if columns <= 1:
            return list(range(columns))

        masses = [
            (self._repeat_mass(cells[:, column]), column)
            for column in range(columns)
        ]
        masses.sort(key=lambda item: (-item[0], item[1]))

        # Only the most repetitive columns participate in the affinity graph.
        active = [
            column for mass, column in masses[:min(48, columns)]
            if mass > 0
        ]

        if len(active) <= 1:
            return [column for _, column in masses]

        position = {column: index for index, column in enumerate(active)}
        size = len(active)
        affinity = np.zeros((size, size), dtype=np.int64)

        # Pair frequencies are accumulated by row-wise value pairs.  The
        # shorter value length rewards prefixes that remain useful in text.
        for left_index in range(size):
            left_column = active[left_index]
            left_values = cells[:, left_column]

            for right_index in range(left_index + 1, size):
                right_column = active[right_index]
                counts = {}

                for row in range(rows):
                    key = (left_values[row], cells[row, right_column])
                    counts[key] = counts.get(key, 0) + 1

                score = 0
                for (left_value, right_value), count in counts.items():
                    if count > 1:
                        score += min(
                            len(left_value),
                            len(right_value),
                        ) * count * (count - 1)

                affinity[left_index, right_index] = score
                affinity[right_index, left_index] = score

        # Start with the strongest pair, then attach columns to either endpoint.
        best_pair = None
        best_value = -1

        for left_index in range(size):
            for right_index in range(left_index + 1, size):
                value = affinity[left_index, right_index]
                candidate = (
                    value,
                    -active[left_index],
                    -active[right_index],
                )
                if best_pair is None or candidate > best_pair[0]:
                    best_pair = (candidate, left_index, right_index)
                    best_value = value

        if best_pair is None or best_value <= 0:
            return [column for _, column in masses]

        _, first, second = best_pair
        chain = [first, second]
        unused = set(range(size))
        unused.remove(first)
        unused.remove(second)

        while unused:
            best = None

            for candidate in unused:
                left_score = affinity[candidate, chain[0]]
                right_score = affinity[candidate, chain[-1]]
                score = max(left_score, right_score)
                endpoint = 0 if left_score >= right_score else 1
                choice = (
                    score,
                    -active[candidate],
                    -endpoint,
                )

                if best is None or choice > best[0]:
                    best = (choice, candidate, endpoint)

            _, candidate, endpoint = best
            if endpoint == 0:
                chain.insert(0, candidate)
            else:
                chain.append(candidate)
            unused.remove(candidate)

        ordered_active = [active[index] for index in chain]
        active_set = set(ordered_active)

        # Deterministic tail: retain the independent frequency ranking.
        tail = [
            column for _, column in masses
            if column not in active_set
        ]
        return ordered_active + tail

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Perform one bounded pairwise refinement pass on the first suffix boundaries."""
        if len(order) < 2 or len(rows) < 2:
            return list(order)

        current = list(order)
        score = self._group_score(cells, rows, current)
        boundary_count = min(12, len(current) - 1)

        for reverse in (False, True):
            positions = (
                range(boundary_count - 1, -1, -1)
                if reverse else range(boundary_count)
            )

            for position in positions:
                trial = current[:]
                trial[position], trial[position + 1] = (
                    trial[position + 1],
                    trial[position],
                )
                trial_score = self._group_score(cells, rows, trial)

                if trial_score > score:
                    current = trial
                    score = trial_score

        return current

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Partition rows by one repeated leading field and rank each group's suffix."""
        rows, columns = cells.shape

        if columns <= 1:
            return [list(range(columns)) for _ in range(rows)]

        lead = max(
            range(columns),
            key=lambda column: (
                self._repeat_mass(cells[:, column]),
                -column,
            ),
        )

        groups = {}
        for row in range(rows):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(columns) if column != lead]
        result = [None] * rows

        for group_rows in groups.values():
            ranked = []

            for column in remaining:
                score = self._repeat_mass(cells[group_rows, column])
                ranked.append((score, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            suffix = [column for _, column in ranked]
            suffix = self._refine_leaf(cells, group_rows, suffix)
            full_order = [lead] + suffix

            for row in group_rows:
                result[row] = full_order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize, score, and lexicographically sort one complete candidate."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate frequency, co-occurrence-seriation, and conditional candidates losslessly."""
        rows, columns = df.shape
        self.num_rows = rows
        self.num_cols = columns

        if rows == 0 or columns == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((rows, columns), dtype=object)

        for row in range(rows):
            for column in range(columns):
                cells[row, column] = self._cell_text(raw[row, column])

        frequency = self._frequency_order(cells)
        cooccurrence = self._cooccurrence_order(cells)
        conditional = self._conditional_orders(cells)

        candidates = [
            [frequency[:] for _ in range(rows)],
            [cooccurrence[:] for _ in range(rows)],
            conditional,
        ]

        best = None

        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, _, row_order, orders = best

        output = np.empty((rows, columns), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            permutation = orders[source]
            output[destination, :] = [
                raw[source, column] for column in permutation
            ]
            column_orders.append([
                df.columns[column] for column in permutation
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders
